/** Poll while an asynchronously created backend object becomes available. */
export const usePollEvents = () => {
    const eventManager = useEventManager();

    const pollEventsMultipleTimes = async (property?: string, action?: EVENT_ACTIONS) => {
        let finished = false;
        let unsubscribe: (() => void) | undefined;
        let timeout: ReturnType<typeof setTimeout> | undefined;
        let wake: (() => void) | undefined;

        const finish = () => {
            if (finished) {
                return;
            }
            finished = true;
            if (timeout !== undefined) {
                clearTimeout(timeout);
            }
            unsubscribe?.();
            wake?.();
        };

        if (property !== undefined && action !== undefined) {
            unsubscribe = eventManager.subscribe((event) => {
                if (finished) {
                    return;
                }
                const updates = (event as unknown as Record<string, { Action: EVENT_ACTIONS }[] | undefined>)[property];
                if (updates?.some((update) => update.Action === action)) {
                    finish();
                }
            });
            // A subscription may invoke its handler before returning its unsubscribe function.
            if (finished) {
                unsubscribe();
            }
        }

        try {
            for (let step = 0; step < maxPollingSteps && !finished; step++) {
                await new Promise<void>((resolve) => {
                    wake = resolve;
                    timeout = setTimeout(resolve, interval);
                });
                wake = undefined;
                timeout = undefined;
                if (finished) {
                    break;
                }
                await eventManager.call();
            }
        } finally {
            finish();
        }
